<?php
require_once __DIR__ . '/config/bootstrap.php';
$slug=trim((string)($_GET['slug']??''));
$stmt=db()->prepare("SELECT * FROM products WHERE slug=? AND is_active=1 LIMIT 1");$stmt->execute([$slug]);$product=$stmt->fetch();
if(!$product){http_response_code(404);$pageTitle='Fragrance not found — Ikki';require __DIR__.'/includes/header.php';echo '<div class="page-wrap"><h1 class="page-title">Fragrance not found</h1><a class="btn" href="/shop.php">Return to collection</a></div>';require __DIR__.'/includes/footer.php';exit;}
$v=db()->prepare("SELECT * FROM product_variants WHERE product_id=? AND is_active=1 ORDER BY volume_ml");$v->execute([$product['id']]);$variants=$v->fetchAll();
$i=db()->prepare("SELECT * FROM product_images WHERE product_id=? ORDER BY is_primary DESC,sort_order");$i->execute([$product['id']]);$images=$i->fetchAll();
$pageTitle=$product['name'].' — Ikki';require __DIR__.'/includes/header.php';
?>
<div class="page-wrap"><div class="detail-grid"><div><img class="detail-image" src="<?= e($images[0]['image_path']??'https://images.unsplash.com/photo-1594035910387-fea47794261f?auto=format&fit=crop&w=1100&q=85') ?>" alt="<?= e($product['name']) ?>"></div><div class="detail-copy"><span class="eyebrow">The Ikki collection</span><h1><?= e($product['name']) ?></h1><p><?= e($product['short_description']??'') ?></p><div class="price"><?= $variants?money($variants[0]['price']):'Currently unavailable' ?></div><?php if($product['description']): ?><p><?= nl2br(e($product['description'])) ?></p><?php endif; ?>
<?php if($variants): ?><form method="post" action="/actions/cart-add.php"><?php echo csrf_field(); ?><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><label class="field-label" for="variant">Choose your size</label><select id="variant" name="variant_id" required><?php foreach($variants as $variant): ?><option value="<?= (int)$variant['id'] ?>" data-price="<?= e((string)$variant['price']) ?>" <?= (int)$variant['stock_quantity']<1?'disabled':'' ?>><?= e($variant['variant_name']) ?> — <?= money($variant['price']) ?> <?= (int)$variant['stock_quantity']<1?'(Sold out)':'' ?></option><?php endforeach; ?></select><label class="field-label" for="quantity">Quantity</label><input class="field qty" id="quantity" type="number" name="quantity" min="1" max="5" value="1"><p><button class="btn" type="submit">Add to bag</button></p></form><?php else: ?><div class="notice">This fragrance is currently unavailable.</div><?php endif; ?>
<?php if($product['top_notes']||$product['heart_notes']||$product['base_notes']): ?><h3>Fragrance notes</h3><?php if($product['top_notes']): ?><p><b>Top:</b> <?= e($product['top_notes']) ?></p><?php endif; ?><?php if($product['heart_notes']): ?><p><b>Heart:</b> <?= e($product['heart_notes']) ?></p><?php endif; ?><?php if($product['base_notes']): ?><p><b>Base:</b> <?= e($product['base_notes']) ?></p><?php endif; ?><?php endif; ?></div></div></div>
<?php require __DIR__.'/includes/footer.php'; ?>
